import { createElement, type SVGProps, useId } from 'react';

// Sourced artwork; see MODEL_LOGO_SOURCES.md for provenance and licenses.
// These logos embed raster artwork (about 100 kB), so they live apart from
// the vector set and load on demand through lazy-raster-brand-icons.ts.

export function HeygenIcon(props: SVGProps<SVGSVGElement>) {
  const id = useId();
  return createElement(
    'svg',
    {
      viewBox: '0 0 132 132',
      fill: 'none',
      'aria-hidden': true,
      focusable: false,
      ...props,
    },
    createElement('rect', {
      width: '131.98',
      height: '131.98',
      fill: `url(#${id}-pattern0_15575_13473)`,
    }),
    createElement(
      'defs',
      {},
      createElement(
        'pattern',
        {
          id: `${id}-pattern0_15575_13473`,
          patternContentUnits: 'objectBoundingBox',
          width: '1',
          height: '1',
        },
        createElement('use', {
          href: `#${id}-image0_15575_13473`,
          transform: 'scale(0.00097561)',
        }),
      ),
      createElement('image', {
        id: `${id}-image0_15575_13473`,
        width: '1025',
        height: '1025',
        preserveAspectRatio: 'none',
        href: 'data:image/png;base64,',
      }),
    ),
  );
}

